self.KB_CONTENT["card:755298"]={"id":"card:755298","ty":"card","sourceId":"755298","title":"『品號資料屬性組合建立作業』中的『屬性代碼十 (MB152)』為何？","ver":"iGP","topic":"品號","keywords":["品號","屬性","代碼"],"y":"other","answer":"* 在畫面上顯示的是屬性代碼名稱，例如：顏色。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
