self.KB_CONTENT["card:751917"]={"id":"card:751917","ty":"card","sourceId":"751917","title":"『立沖帳目明細清除作業』中的『清除未結案之立沖帳目』為何？","ver":"iGP","topic":"立沖帳目","keywords":["立沖帳目","明細","結案","未結"],"y":"other","answer":"* 預設N。* 若清除未結案之立沖帳目為Y，則 [清除未沖銷完畢之立沖帳目] 選項才可輸入；否則，不可輸入。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
