self.KB_CONTENT["card:782870"]={"id":"card:782870","ty":"card","sourceId":"782870","title":"『BOM用量資料建立』中的『變更單號 (MC006-MC007-MC008)』為何？","ver":"GP4以上","topic":"變更單","keywords":["變更單","單別","單號","用量"],"y":"other","answer":"* 記錄最後一個版次的工程變更單的單別及單號。* 工程變更單確認時回寫此欄位，無法自行修改。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
