self.KB_CONTENT["card:777188"]={"id":"card:777188","ty":"card","sourceId":"777188","title":"『多角貿易結帳單拋轉作業』中的『拋轉性質』為何？","ver":"GP4以上","topic":"多角貿易","keywords":["多角貿易","採購單","結帳單","訂單"],"y":"other","answer":"* 可選擇1.訂單拋轉或2.採購單拋轉。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
self.KB_CONTENT["card:777643"]={"id":"card:777643","ty":"card","sourceId":"777643","title":"『託外驗退件退回作業』中的『原進貨量』為何？","ver":"GP4以上","topic":"進貨單","keywords":["進貨單"],"y":"other","answer":"* 為原託外進貨單之進貨數量。* 不可輸入或更改。僅作顯示。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
