self.KB_CONTENT["field:752189"]={"id":"field:752189","ty":"field","sourceId":"752189","title":"單別名稱","ver":"iGP","topic":"","keywords":[],"job":"分錄性質設定-領料單","code":"","answer":"* 依照單別資料自動顯示單別名稱，僅作顯示不可修改。","file":"fields.jsonl"};
